<?php

declare(strict_types=1);
require_once __DIR__.'/CompanyBankReversalSchema.php';require_once __DIR__.'/CompanyBankReversalData.php';require_once __DIR__.'/CompanyBankReceiptComponents.php';
/** Append-only full reversals. Original native cash and component evidence remain byte-for-byte unchanged. */
final class CompanyBankReceiptReversals
{
    public function __construct(private $db,private string $p){if(!preg_match('/^[A-Za-z0-9_]+$/D',$p))throw new InvalidArgumentException('Invalid table prefix');}
    public function tables():array{return array_values(array_unique(array_merge((new CompanyBankReceiptComponents($this->db,$this->p))->tables(),['company_bank_receipt_reversals'])));}
    private function rows(string $sql,array $args=[]):array{return IssuerStorage::query($this->db,$sql,$args)->result_array();}
    private static function json(array $data):string{return json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
    private function boundary(int $issuer,int $actor,bool $write):void
    {
        IssuerTransaction::assertOwned($this->db,$this->p,$this->tables());CompanyBankReversalSchema::assertValid($this->db,$this->p);$acl=new IssuerResourceAccess($this->db,$this->p);if(!$acl->can($issuer,$actor,'invoices','view')||($write&&!$acl->can($issuer,$actor,'payments','delete')))throw new DomainException('company_bank_reversal_access_denied');
    }
    private function originalFromComponents(int $issuer,int $invoice,int $payment,array $all):array
    {
        $parent=$this->rows('SELECT i.id,i.total,i.currency,i.status,p.date FROM '.$this->p.'invoices i JOIN '.$this->p.'issuers_invoice_documents d ON d.invoice_id=i.id AND d.issuer_id=i.issuer_id JOIN '.$this->p.'invoicepaymentrecords p ON p.invoiceid=i.id WHERE i.id=? AND i.issuer_id=? AND p.id=? FOR UPDATE',[$invoice,$issuer,$payment])[0]??null;if(!$parent||!isset($all[$payment]))throw new DomainException('company_bank_reversal_original_review');$dto=CompanyBankComponentsData::fromCaptured($all[$payment]);$receipt=$this->rows('SELECT request_key FROM '.$this->p.'company_payment_receipts WHERE issuer_id=? AND invoice_id=? AND payment_id=? FOR UPDATE',[$issuer,$invoice,$payment]);if(count($receipt)!==1)throw new DomainException('company_bank_reversal_original_review');$unit=(new CompanyCurrencyUnits($this->db,$this->p))->resolveRead($parent['currency']);return ['parent'=>$parent,'original'=>$dto,'receipt_key'=>$receipt[0]['request_key'],'unit'=>$unit];
    }
    private function original(int $issuer,int $actor,int $invoice,int $payment):array{return $this->originalFromComponents($issuer,$invoice,$payment,(new CompanyBankReceiptComponents($this->db,$this->p))->forInvoiceInOwned($issuer,$actor,$invoice));}
    private static function expectedKey(int $issuer,int $payment,string $originalKey):string{return hash('sha256',json_encode(['bb-full-external-reversal',$issuer,$payment,$originalKey],JSON_THROW_ON_ERROR));}
    private function decode(int $issuer,int $invoice,array $row,array $original):CompanyBankReversalData
    {
        try{$data=json_decode($row['payload_json'],true,16,JSON_THROW_ON_ERROR);if(!is_array($data))throw new DomainException();$dto=CompanyBankReversalData::fromCaptured($data,$original['original']);}catch(Throwable $e){throw new DomainException('company_bank_reversal_receipt_review');}
        if($row['request_key']!==self::expectedKey($issuer,(int)$row['payment_id'],$original['receipt_key'])||(int)$row['issuer_id']!==$issuer||(int)$row['invoice_id']!==$invoice||$row['source_type']!==$dto->sourceType()||$row['original_receipt_key']!==$original['receipt_key']||$row['original_receipt_key']!==$data['original_receipt_key']||$row['original_components_hash']!==$original['original']->fingerprint()||$row['currency']!==$original['unit']['iso_code']||$row['currency']!==$data['currency']||$row['currency_basis']!==$original['unit']['basis']||$row['book_date']!==$data['book_date']||$row['book_date']<$original['parent']['date']||$row['external_reference_key']!==$dto->externalReferenceKey()||!hash_equals($row['payload_hash'],hash('sha256',$row['payload_json']))||!hash_equals($row['payload_hash'],$dto->fingerprint())||$row['payload_json']!==self::json($dto->data()))throw new DomainException('company_bank_reversal_receipt_review');
        foreach(['cash_principal_reversed','principal_reinstated','discount_reversed','abatement_reversed','charges_aggregate_reversed','returned_paid','net_reversed'] as $field)if(CompanyInvoiceAmounts::minor((string)$row[$field])!==CompanyInvoiceAmounts::minor($data[$field]))throw new DomainException('company_bank_reversal_receipt_review');$header=[$row['request_key'],$issuer,$invoice,(int)$row['payment_id'],$row['source_type'],$row['original_receipt_key'],$row['currency'],$row['currency_basis'],$row['payload_hash'],(int)$row['created_by'],$row['created_at']];if(!hash_equals($row['record_hash'],hash('sha256',self::json($header))))throw new DomainException('company_bank_reversal_receipt_review');return $dto;
    }
    public function capturedInOwned($issuer,$actor,$invoice,$payment):?CompanyBankReversalData
    {
        $issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);$invoice=IssuerPolicy::id($invoice);$payment=IssuerPolicy::id($payment);$this->boundary($issuer,$actor,true);$original=$this->original($issuer,$actor,$invoice,$payment);$rows=$this->rows('SELECT * FROM '.$this->p.'company_bank_receipt_reversals WHERE payment_id=? FOR UPDATE',[$payment]);if(count($rows)>1)throw new DomainException('company_bank_reversal_receipt_review');return $rows?$this->decode($issuer,$invoice,$rows[0],$original):null;
    }
    /** Caller is the canonical writer with an exact allowlisted final proof adapter. */
    public function recordInOwned($issuer,$actor,$invoice,$payment,string $key,CompanyBankReversalData $dto):bool
    {
        $issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);$invoice=IssuerPolicy::id($invoice);$payment=IssuerPolicy::id($payment);if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new DomainException('company_bank_reversal_invalid');$this->boundary($issuer,$actor,true);$original=$this->original($issuer,$actor,$invoice,$payment);$data=$dto->data();if($key!==self::expectedKey($issuer,$payment,$original['receipt_key']))throw new DomainException('company_bank_reversal_invalid');$expected=CompanyBankReversalData::fromCaptured($data,$original['original']);if($data['original_receipt_key']!==$original['receipt_key']||$data['book_date']<$original['parent']['date'])throw new DomainException('company_bank_reversal_original_review');$old=$this->rows('SELECT * FROM '.$this->p.'company_bank_receipt_reversals WHERE payment_id=? OR request_key=? FOR UPDATE',[$payment,$key]);if($old){if(count($old)!==1||$old[0]['request_key']!==$key||(int)$old[0]['payment_id']!==$payment||!hash_equals($this->decode($issuer,$invoice,$old[0],$original)->fingerprint(),$expected->fingerprint()))throw new DomainException('company_bank_reversal_receipt_conflict');return false;}
        if($this->rows('SELECT request_key FROM '.$this->p.'company_bank_receipt_reversals WHERE external_reference_key=? FOR UPDATE',[$dto->externalReferenceKey()]))throw new DomainException('company_bank_reversal_external_reference_reused');$now=gmdate('Y-m-d H:i:s');$row=['request_key'=>$key,'issuer_id'=>$issuer,'invoice_id'=>$invoice,'payment_id'=>$payment,'source_type'=>$dto->sourceType(),'original_receipt_key'=>$data['original_receipt_key'],'original_components_hash'=>$data['original_components_hash'],'external_reference_key'=>$dto->externalReferenceKey(),'currency'=>$data['currency'],'currency_basis'=>$original['unit']['basis']];foreach(['cash_principal_reversed','principal_reinstated','discount_reversed','abatement_reversed','charges_aggregate_reversed','returned_paid','net_reversed','book_date'] as $field)$row[$field]=$data[$field];$row+=['payload_json'=>self::json($data),'payload_hash'=>$dto->fingerprint(),'created_by'=>$actor,'created_at'=>$now];$row['record_hash']=hash('sha256',self::json([$key,$issuer,$invoice,$payment,$row['source_type'],$row['original_receipt_key'],$row['currency'],$row['currency_basis'],$row['payload_hash'],$actor,$now]));IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'company_bank_receipt_reversals (`'.implode('`,`',array_keys($row)).'`) VALUES('.implode(',',array_fill(0,count($row),'?')).')',array_values($row));$saved=$this->rows('SELECT * FROM '.$this->p.'company_bank_receipt_reversals WHERE request_key=? AND issuer_id=?',[$key,$issuer])[0]??null;if(!$saved||!hash_equals($this->decode($issuer,$invoice,$saved,$original)->fingerprint(),$dto->fingerprint()))throw new RuntimeException('issuer_bank_reversal_write_unconfirmed');$meta=self::json(['request_key'=>$key,'invoice_id'=>$invoice,'payment_id'=>$payment,'payload_hash'=>$dto->fingerprint(),'basis'=>$data['basis']]);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at,metadata_json) VALUES(?,?,?,?,?,?)',[$actor,'company_bank_external_reversal_declared',$issuer,$invoice,$now,$meta]);$audit=(int)$this->db->insert_id();if(!$this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND issuer_id=? AND metadata_json=?',[$audit,$issuer,$meta]))throw new RuntimeException('issuer_bank_reversal_write_unconfirmed');return true;
    }
    public function forInvoiceInOwned($issuer,$actor,$invoice):array
    {
        $issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);$invoice=IssuerPolicy::id($invoice);$this->boundary($issuer,$actor,false);$all=(new CompanyBankReceiptComponents($this->db,$this->p))->forInvoiceInOwned($issuer,$actor,$invoice);$rows=$this->rows('SELECT * FROM '.$this->p.'company_bank_receipt_reversals WHERE invoice_id=? ORDER BY payment_id FOR UPDATE',[$invoice]);$result=[];foreach($rows as $row){if((int)$row['issuer_id']!==$issuer||isset($result[(int)$row['payment_id']]))throw new DomainException('company_bank_reversal_receipt_review');$original=$this->originalFromComponents($issuer,$invoice,(int)$row['payment_id'],$all);$result[(int)$row['payment_id']]=$this->decode($issuer,$invoice,$row,$original)->data();}return $result;
    }
    public function forPortalInOwned(CompanyPortalInvoices|NativeCompanyPublicInvoice $portal,array $session,$issuer,$invoice):array
    {
        $issuer=IssuerPolicy::id($issuer);$invoice=IssuerPolicy::id($invoice);IssuerTransaction::assertOwned($this->db,$this->p,array_values(array_unique(array_merge($this->tables(),$portal->balanceTables()))));CompanyBankReversalSchema::assertValid($this->db,$this->p);$identity=$portal->balanceIdentityInOwnedTransaction($session,$issuer,$invoice,$this->db,$this->p);$all=(new CompanyBankReceiptComponents($this->db,$this->p))->forPortalInOwned($portal,$session,$issuer,$invoice);$rows=$this->rows('SELECT * FROM '.$this->p.'company_bank_receipt_reversals WHERE invoice_id=? ORDER BY payment_id FOR UPDATE',[$invoice]);$result=[];foreach($rows as $row){if((int)$row['issuer_id']!==$issuer||isset($result[(int)$row['payment_id']]))throw new DomainException('company_bank_reversal_receipt_review');$original=$this->originalFromComponents($issuer,$invoice,(int)$row['payment_id'],$all);$result[(int)$row['payment_id']]=$this->decode($issuer,$invoice,$row,$original)->data();}if($identity!==$portal->balanceIdentityInOwnedTransaction($session,$issuer,$invoice,$this->db,$this->p))throw new DomainException('company_portal_invoice_unavailable');return $result;
    }

}
